function isIsomorphic(s, t) {
  const getPattern = str => {
    let result = '';
    for (let i = 0; i < str.length; i++) {
      result += str.indexOf(str[i]) + ',';
    }
    return result;
  };
  return getPattern(s) === getPattern(t);
}

